#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m15-dns-detective pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m15-dns-detective
CHECKS="api-service api-endpoints probe-short-name"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m15-dns-detective
checks:
  - id: api-service
    describe: The Service shelf-api exists, on port 8081
    kubectl:
      - get
      - service
      - shelf-api
      - -n
      - shelf
      - -o
      - jsonpath={.spec.ports[0].port}
    expect:
      equals: "8081"
    hint: "Clients ask for the name shelf-api, and the Service in the cluster has another name. Run `kubectl get services --namespace shelf` and compare the name with the one in the clients' URLs. A Service's name can't be changed: fix `dns-detective/shelf-api-service.yaml`, delete the old Service, and apply the file."
  - id: api-endpoints
    describe: The Service shelf-api has one ready endpoint
    kubectl:
      - get
      - endpointslices
      - -n
      - shelf
      - -l
      - kubernetes.io/service-name=shelf-api
      - -o
      - jsonpath={.items[*].endpoints[*].conditions.ready}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: "true"
    hint: "The Service needs a ready api Pod behind it. Its selector is `app.kubernetes.io/name: shelf-api`. Run `kubectl get endpointslices --namespace shelf`."
  - id: probe-short-name
    describe: A request from shelf-probe to http://shelf-api:8081/healthz succeeds, by the short name
    kubectl:
      - exec
      - shelf-probe
      - -n
      - shelf
      - --
      - wget
      - -qO-
      - -T
      - "3"
      - http://shelf-api:8081/healthz
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          exitCode: 0
    hint: "The probe is in the namespace shelf, so the short name completes to the Service's full name: that works once the Service has the right name. Run `kubectl exec shelf-probe --namespace shelf -- wget -qO- -T 3 http://shelf-api:8081/healthz`."
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
